    public struct DetLinearKFModelFloat : IfloatKFModel
    {
        public floatMxN A;
        public floatMxN B;
        public floatN Scratch;

        public void F(in floatN x, in floatN u, ref floatN xNext)
        {
            Blas.dot(in A, in x, ref xNext);
            Blas.dot(in B, in u, ref Scratch);
            xNext.addInPlace(Scratch);
        }

        public void JacobianF(in floatN x, in floatN u, ref floatMxN J)
        {
            for (int r = 0; r < A.M_Rows; r++) for (int c = 0; c < A.N_Cols; c++) J[r, c] = A[r, c];
        }
    }

    public struct DetLinearKFMeasFloat : IfloatKFMeasurement
    {
        public floatMxN Hmat;

        public void H(in floatN x, ref floatN z) => Blas.dot(in Hmat, in x, ref z);

        public void JacobianH(in floatN x, ref floatMxN J)
        {
            for (int r = 0; r < Hmat.M_Rows; r++) for (int c = 0; c < Hmat.N_Cols; c++) J[r, c] = Hmat[r, c];
        }
    }

    public struct DetPolyResidualFloat : IfloatResidualFunction
    {
        public floatN X, Y;

        public void Residuals(in floatN p, ref floatN r)
        {
            for (int i = 0; i < r.N; i++)
            {
                float x = X[i];
                float model = p[0] + p[1] * x + p[2] * x * x;
                r[i] = model - Y[i];
            }
        }
    }

    public struct DetPolyCurveModelFloat : IfloatCurveModel
    {
        public float Eval(float x, in floatN p) => p[0] + p[1] * x + p[2] * x * x;
    }

